css:
:root {
    margin: 0;
    padding:0;
}
@media print {
  * {
    -webkit-print-color-adjust: exact !important;
    print-color-adjust: exact !important;
    color-adjust: exact !important;
  }
}
.print-format {
    padding: 0;
    margin:0;
}
.section-break {
    padding:0;
    margin-top: 30px;
}

.sc-preview-wrapper {
		
		padding: 24px 28px;
		color:  #1a1a2e;
	}
.sc-cr-header {
	display: flex;
	align-items: flex-start;
	justify-content: space-between;
	margin-bottom: 28px;
	padding-bottom: 18px;
	border-bottom: 2px solid  #e2e8f0;
}
.sc-cr-title {
	font-size: 1.6rem;
	font-weight: 700;
	color:  #1e3a5f;
	margin: 0 0 6px;
	text-align: center;
}
.sc-cr-meta {
	font-size: 0.82rem;
	color:  #64748b;
	display: flex;
	flex-wrap: wrap;
}
.sc-cr-meta span { display: flex; align-items: center; gap: 4px; }
.sc-status-badge {
	display: inline-block;
	padding: 3px 12px;
	border-radius: 999px;
	font-size: 0.78rem;
	font-weight: 600;
	background:  #4f46e5;
	color: #fff;
}

.sc-section { margin-bottom: 28px; }
.sc-section-title {
	font-size: 1.3rem;
	font-weight: 700;
	letter-spacing: 0.12em;
	text-transform: uppercase;
	color:  #596370;
	margin-bottom: 10px;
}
.sc-analysts-list { display: flex; flex-wrap: wrap; gap: 8px; }

.sc-scopes-list { display: flex; flex-direction: column; gap: 6px; }
.sc-scope-row {
	background:  #f8fafc;
	border: 1px solid  #e2e8f0;
	border-radius: 6px;
	padding: 8px 14px;
	font-size: 0.88rem;
	color:  #334155;
	margin-bottom: 0.5rem;
}
.sc-sep { color:  #94a3b8; margin: 0 6px; }
.sc-requirement-block {
	border-left: 3px solid  #4f46e5;
	padding: 10px 16px;
	margin-bottom: 16px;
	background:  #f8fafc;
	border-radius: 0 6px 6px 0;
}
.sc-req-title {
	font-size: 1rem;
	font-weight: 600;
	color:  #1e3a5f;
	margin: 0 0 6px;
}
.sc-req-note {
	font-size: 0.875rem;
	color:  #475569;
	margin: 0;
	white-space: pre-wrap;
}
.sc-uat-content {
	font-size: 0.875rem;
	color:  #475569;
	font-weight: 600;
}
